import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { api } from "../../api";

const styles = {
  page: {
    minHeight: "100vh",
    backgroundColor: "#0b0c10",
    color: "#fff",
    padding: "40px 24px",
  },

  title: {
    color: "#ec4899",
    fontSize: "28px",
    marginBottom: "24px",
  },

  card: {
    backgroundColor: "#111318",
    border: "1px solid #1f2128",
    borderRadius: "12px",
    padding: "16px",
    marginBottom: "12px",
  },

  meta: {
    color: "#9ca3af",
    fontSize: "14px",
  },

  total: {
    fontSize: "20px",
    fontWeight: "bold",
    marginTop: "20px",
  },

  button: {
    width: "100%",
    padding: "14px",
    marginTop: "20px",
    backgroundColor: "#ec4899",
    color: "#fff",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    fontWeight: "bold",
    fontSize: "16px",
  },
};

export default function Checkout() {
  const { state } = useLocation();
  const navigate = useNavigate();

  const item = state?.item;

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  if (!item) {
    return (
      <div style={styles.page}>
        <h1 style={styles.title}>Checkout</h1>
        <p style={styles.meta}>
          Data checkout tidak ditemukan.
        </p>
      </div>
    );
  }

  const total = Number(item.price) * Number(item.quantity);

  const handlePay = async () => {
    try {
      setLoading(true);
      setError("");

      const res = await api.checkout({
        event_id: Number(item.event_id),
        ticket_type_id: Number(item.ticket_type_id),
        quantity: Number(item.quantity),
      });

      const redirectUrl = res?.data?.snap_redirect_url;

      if (redirectUrl) {
        window.location.href = redirectUrl;
        return;
      }

      if (res?.data?.order?.id) {
        navigate(`/order/${res.data.order.id}`);
        return;
      }

      throw new Error(
        "Snap URL tidak ditemukan dari server."
      );
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.title}>Checkout</h1>

      <div style={styles.card}>
        <h3>{item.event_title}</h3>

        <p style={styles.meta}>
          {item.ticket_type_name}
        </p>

        <p style={styles.meta}>
          Jumlah: {item.quantity}
        </p>

        <p style={styles.meta}>
          Harga:
          {" "}
          Rp {Number(item.price).toLocaleString("id-ID")}
        </p>
      </div>

      <p style={styles.total}>
        Total:
        {" "}
        <span style={{ color: "#ec4899" }}>
          Rp {total.toLocaleString("id-ID")}
        </span>
      </p>

      {error && (
        <p style={{ color: "#f87171" }}>
          {error}
        </p>
      )}

      <button
        style={styles.button}
        onClick={handlePay}
        disabled={loading}
      >
        {loading ? "Memproses..." : "Bayar Sekarang"}
      </button>
    </div>
  );
}
