import React, { createContext, useContext, useState, useEffect, useCallback } from "react";
import { api } from "../../api";

const AdminContext = createContext(null);

export function AdminProvider({ children }) {
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [events, setEvents] = useState([]);
  const [orders, setOrders] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadDashboard = useCallback(async () => {
    try {
      const res = await api.getAdminDashboard();
      setStats(res.data || null);
    } catch (err) {
      console.error("Gagal memuat dashboard admin", err);
    }
  }, []);

  const loadUsers = useCallback(async () => {
    try {
      const res = await api.getUsers();
      const raw = res.data ?? res;
      setUsers(Array.isArray(raw) ? raw : []);
    } catch (err) {
      console.error("Gagal memuat users", err);
    }
  }, []);

  const loadEvents = useCallback(async () => {
    try {
      const data = await api.getEvents({ status: "all" });
      setEvents(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Gagal memuat events", err);
    }
  }, []);

  const loadOrders = useCallback(async () => {
    try {
      const res = await api.getAllOrders();
      const raw = res.data ?? res;
      setOrders(Array.isArray(raw) ? raw : []);
    } catch (err) {
      console.error("Gagal memuat orders", err);
    }
  }, []);

  const loadReviews = useCallback(async () => {
    try {
      const res = await api.getOrganizerReviews();
      const raw = res.data ?? res;
      setReviews(Array.isArray(raw) ? raw : []);
    } catch (err) {
      console.error("Gagal memuat reviews", err);
    }
  }, []);

  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await Promise.all([
        loadDashboard(),
        loadUsers(),
        loadEvents(),
        loadOrders(),
        loadReviews(),
      ]);
      setLoading(false);
    };
    init();
  }, [loadDashboard, loadUsers, loadEvents, loadOrders, loadReviews]);

  const approveEvent = async (id) => {
    try {
      await api.moderateEventStatus(id, { status: "approved" });
      await loadEvents();
      await loadDashboard();
    } catch (err) {
      console.error("Gagal approve event", err);
      throw err;
    }
  };

  const rejectEvent = async (id, reject_reason = "") => {
    try {
      await api.moderateEventStatus(id, { status: "rejected", reject_reason });
      await loadEvents();
      await loadDashboard();
    } catch (err) {
      console.error("Gagal reject event", err);
      throw err;
    }
  };

  const deleteEvent = async (id) => {
    try {
      await api.deleteEvent(id);
      await loadEvents();
      await loadDashboard();
    } catch (err) {
      console.error("Gagal hapus event", err);
      throw err;
    }
  };

  const suspendUser = async (id) => {
    try {
      await api.updateUserStatus(id, "suspended");
      await loadUsers();
    } catch (err) {
      console.error("Gagal suspend user", err);
      throw err;
    }
  };

  const activateUser = async (id) => {
    try {
      await api.updateUserStatus(id, "active");
      await loadUsers();
    } catch (err) {
      console.error("Gagal activate user", err);
      throw err;
    }
  };

  const changeUserRole = async (id, role) => {
    try {
      await api.updateUserRole(id, role);
      await loadUsers();
    } catch (err) {
      console.error("Gagal ubah role user", err);
      throw err;
    }
  };

  const deleteUser = async (id) => {
    try {
      await api.deleteUser(id);
      await loadUsers();
    } catch (err) {
      console.error("Gagal hapus user", err);
      throw err;
    }
  };

  const updateOrderStatus = async (id, status) => {
    try {
      await api.updateOrderStatus(id, { status });
      await loadOrders();
    } catch (err) {
      console.error("Gagal update order status", err);
      throw err;
    }
  };

  const deleteReview = async (id) => {
    try {
      await api.deleteReview(id);
      await loadReviews();
    } catch (err) {
      console.error("Gagal hapus review", err);
      throw err;
    }
  };

  const getEventById = (id) => {
    return events.find((event) => String(event.id) === String(id));
  };

  const getOrderById = (id) => {
    return orders.find((order) => String(order.id) === String(id));
  };

  const value = {
    loading,
    stats,

    users,
    events,
    orders,
    reviews,

    approveEvent,
    rejectEvent,
    deleteEvent,

    suspendUser,
    activateUser,
    changeUserRole,
    deleteUser,

    updateOrderStatus,
    deleteReview,

    getEventById,
    getOrderById,

    reload: {
      dashboard: loadDashboard,
      users: loadUsers,
      events: loadEvents,
      orders: loadOrders,
      reviews: loadReviews,
    },
  };

  return (
    <AdminContext.Provider value={value}>
      {children}
    </AdminContext.Provider>
  );
}

export function useAdmin() {
  const context = useContext(AdminContext);

  if (!context) {
    throw new Error("useAdmin harus digunakan di dalam AdminProvider");
  }

  return context;
}

export default AdminContext;
