import { useState } from "react";
import { X, Star } from "lucide-react";
import { api } from "../api";

export default function ReviewModal({
  isOpen,
  onClose,
  eventId,
  onSuccess,
}) {
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const submitReview = async () => {
    try {
      setLoading(true);

      await api.createReview({
        event_id: eventId,
        rating,
        comment,
      });

      alert("Review berhasil dikirim");

      onSuccess?.();
      onClose();
    } catch (err) {
      alert(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,.75)",
        display: "grid",
        placeItems: "center",
        zIndex: 999,
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "500px",
          background: "#161826",
          borderRadius: "24px",
          padding: "24px",
          border: "1px solid #25293d",
        }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginBottom: "20px",
          }}
        >
          <h2>Beri Ulasan</h2>

          <button
            onClick={onClose}
            style={{
              background: "transparent",
              border: "none",
              color: "#fff",
              cursor: "pointer",
            }}
          >
            <X />
          </button>
        </div>

        <div
          style={{
            display: "flex",
            gap: "8px",
            marginBottom: "20px",
          }}
        >
          {[1, 2, 3, 4, 5].map((n) => (
            <Star
              key={n}
              size={32}
              onClick={() => setRating(n)}
              style={{
                cursor: "pointer",
                fill: n <= rating ? "#facc15" : "transparent",
                color: "#facc15",
              }}
            />
          ))}
        </div>

        <textarea
          rows={5}
          placeholder="Bagaimana pengalamanmu di event ini?"
          value={comment}
          onChange={(e) => setComment(e.target.value)}
          style={{
            width: "100%",
            padding: "14px",
            borderRadius: "14px",
            background: "#0f111a",
            border: "1px solid #2b3148",
            color: "#fff",
            resize: "none",
          }}
        />

        <button
          onClick={submitReview}
          disabled={loading}
          style={{
            width: "100%",
            marginTop: "20px",
            padding: "14px",
            borderRadius: "14px",
            border: "none",
            cursor: "pointer",
            color: "#fff",
            fontWeight: "bold",
            background:
              "linear-gradient(135deg,#ec4899,#db2777)",
          }}
        >
          {loading ? "Mengirim..." : "Kirim Ulasan"}
        </button>
      </div>
    </div>
  );
}