import { useEffect, useState, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Calendar,
  Ticket,
  CreditCard,
  Star,
  ArrowLeft,
  Loader2,
  AlertCircle,
} from "lucide-react";

import { api } from "../../api";
import ReviewModal from "../../components/ReviewModal";

export default function OrderDetail() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [reviewOpen, setReviewOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  const loadOrder = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      const res = await api.getOrderById(id);
      setOrder(res.data);
    } catch (err) {
      setError(err.message || "Gagal memuat detail order.");
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => {
    loadOrder();
  }, [loadOrder]);

  const checkPayment = async () => {
    try {
      setActionLoading(true);
      const res = await api.checkPaymentStatus(id);

      if (res.order) {
        setOrder(res.order);
      }

      alert(res.message || "Status pembayaran diperbarui");
    } catch (err) {
      alert(err.message || "Gagal memeriksa status pembayaran");
    } finally {
      setActionLoading(false);
    }
  };

  const cancelOrder = async () => {
    const ok = window.confirm("Batalkan pesanan ini?");
    if (!ok) return;

    try {
      setActionLoading(true);
      await api.cancelMyOrder(id);
      await loadOrder();
      alert("Order berhasil dibatalkan");
    } catch (err) {
      alert(err.message || "Gagal membatalkan order");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) {
    return (
      <div
        style={{
          minHeight: "100vh",
          background: "#0b0c10",
          color: "#fff",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          gap: "12px",
        }}
      >
        <Loader2
          size={36}
          color="#ec4899"
          style={{ animation: "spin 1s linear infinite" }}
        />
        <span style={{ color: "#9ca3af" }}>Memuat detail pesanan...</span>
      </div>
    );
  }

  if (error || !order) {
    return (
      <div
        style={{
          minHeight: "100vh",
          background: "#0b0c10",
          color: "#fff",
          padding: "32px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            backgroundColor: "#7f1d1d",
            color: "#fca5a5",
            padding: "16px 24px",
            borderRadius: "14px",
            display: "flex",
            alignItems: "center",
            gap: "10px",
            marginBottom: "16px",
          }}
        >
          <AlertCircle size={20} />
          <span>{error || "Order tidak ditemukan"}</span>
        </div>
        <button
          onClick={() => navigate("/history")}
          style={{
            background: "#ec4899",
            color: "#fff",
            border: "none",
            borderRadius: "10px",
            padding: "10px 20px",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Kembali ke Riwayat
        </button>
      </div>
    );
  }

  return (
    <>
      <div
        style={{
          minHeight: "100vh",
          background: "#0b0c10",
          color: "#fff",
          padding: "32px",
        }}
      >
        <div
          style={{
            maxWidth: "1000px",
            margin: "0 auto",
          }}
        >
          <button
            onClick={() => navigate("/history")}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "8px",
              background: "transparent",
              border: "none",
              color: "#ec4899",
              cursor: "pointer",
              fontWeight: "600",
              fontSize: "14px",
              marginBottom: "20px",
              padding: 0,
            }}
          >
            <ArrowLeft size={18} />
            Kembali ke Riwayat Transaksi
          </button>

          <div
            style={{
              background: "#161826",
              borderRadius: "24px",
              overflow: "hidden",
              border: "1px solid #25293d",
            }}
          >
            {order.event?.image && (
              <img
                src={order.event.image}
                alt={order.event.title}
                style={{
                  width: "100%",
                  height: "320px",
                  objectFit: "cover",
                }}
              />
            )}

            <div style={{ padding: "24px" }}>
              <h1
                style={{
                  fontSize: "30px",
                  marginBottom: "14px",
                }}
              >
                {order.event?.title}
              </h1>

              <p style={{ color: "#9ca3af" }}>
                {order.event?.artist}
              </p>

              <div
                style={{
                  display: "grid",
                  gap: "12px",
                  marginTop: "20px",
                }}
              >
                <div>
                  <Calendar size={16} />
                  {" "}
                  {order.event?.event_date
                    ? new Date(order.event.event_date).toLocaleDateString("id-ID")
                    : "-"}
                </div>

                <div>
                  <Ticket size={16} />
                  {" "}
                  {order.ticket_type?.name}
                </div>

                <div>
                  <CreditCard size={16} />
                  {" "}
                  {order.payment_method}
                </div>
              </div>

              <hr
                style={{
                  margin: "24px 0",
                  borderColor: "#25293d",
                }}
              />

              <h3>Ringkasan Pembayaran</h3>

              <p>
                Kode Pesanan: <strong>{order.order_code}</strong>
              </p>

              <p>
                Quantity: {order.quantity}
              </p>

              <p>
                Total:
                {" "}
                Rp{" "}
                {Number(order.total).toLocaleString("id-ID")}
              </p>

              <p>
                Status:
                {" "}
                <b
                  style={{
                    color:
                      order.status === "paid"
                        ? "#22c55e"
                        : order.status === "pending"
                        ? "#facc15"
                        : "#ef4444",
                  }}
                >
                  {order.status?.toUpperCase()}
                </b>
              </p>

              <div
                style={{
                  display: "flex",
                  gap: "12px",
                  flexWrap: "wrap",
                  marginTop: "24px",
                }}
              >
                {order.status === "pending" && (
                  <>
                    <button
                      onClick={checkPayment}
                      disabled={actionLoading}
                      style={btnPink}
                    >
                      {actionLoading ? "Memeriksa..." : "Cek Pembayaran"}
                    </button>

                    <button
                      onClick={cancelOrder}
                      disabled={actionLoading}
                      style={btnDanger}
                    >
                      Batalkan Order
                    </button>
                  </>
                )}

                {order.status === "paid" && (
                  <>
                    <button
                      onClick={() => setReviewOpen(true)}
                      style={btnPink}
                    >
                      <Star size={18} />
                      Beri Review
                    </button>

                    <button
                      onClick={() => navigate("/my-tickets")}
                      style={btnSecondary}
                    >
                      <Ticket size={18} />
                      Lihat E-Tiket Saya
                    </button>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <ReviewModal
        isOpen={reviewOpen}
        eventId={order.event?.id}
        onClose={() => setReviewOpen(false)}
        onSuccess={loadOrder}
      />
    </>
  );
}

const btnPink = {
  background:
    "linear-gradient(135deg,#ec4899,#db2777)",
  color: "#fff",
  border: "none",
  borderRadius: "14px",
  padding: "12px 18px",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  gap: "8px",
  fontWeight: "bold",
};

const btnDanger = {
  background: "#dc2626",
  color: "#fff",
  border: "none",
  borderRadius: "14px",
  padding: "12px 18px",
  cursor: "pointer",
  fontWeight: "bold",
};

const btnSecondary = {
  background: "#1e2235",
  color: "#fff",
  border: "1px solid #282c42",
  borderRadius: "14px",
  padding: "12px 18px",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  gap: "8px",
  fontWeight: "bold",
};
